# Copies this project to a new location without "file name too long" errors.
#
#   powershell -ExecutionPolicy Bypass -File scripts\copy-project.ps1 -Destination C:\Projects\INV-MOBILE-APP
#
# Use this instead of Explorer copy/paste. Android/Gradle build caches - the only
# files with paths past 260 characters - are left behind; they are regenerated by the
# next build. node_modules is copied too (no internet needed). Add -FreshInstall to
# skip node_modules and run `npm ci` at the destination instead (smaller, faster copy).

param(
  [Parameter(Mandatory = $true)][string]$Destination,
  [switch]$FreshInstall
)

$ErrorActionPreference = 'Stop'
$src = Split-Path -Parent $PSScriptRoot
$dst = [System.IO.Path]::GetFullPath($Destination)
if ($dst.TrimEnd('\') -ieq $src.TrimEnd('\')) { throw 'Destination is this folder.' }
if ($dst.StartsWith($src.TrimEnd('\') + '\', [System.StringComparison]::OrdinalIgnoreCase)) {
  throw 'Destination cannot be inside the project folder.'
}
if ((Test-Path -LiteralPath $dst) -and (Get-ChildItem -LiteralPath $dst -Force | Select-Object -First 1)) {
  throw "Destination $dst is not empty. Choose a new or empty folder."
}

# Exact Gradle cache folders to leave behind (same rules as clean-native-caches.ps1).
$xd = @(& (Join-Path $PSScriptRoot 'clean-native-caches.ps1') -ListOnly)
if ($FreshInstall) { $xd += (Join-Path $src 'node_modules') }
Write-Host "Copying $src -> $dst (skipping $($xd.Count) cache folders)"

$rcArgs = @($src, $dst, '/E', '/MT:16', '/R:1', '/W:1', '/NFL', '/NDL', '/NJH', '/NP')
if ($xd.Count -gt 0) { $rcArgs += '/XD'; $rcArgs += $xd }
robocopy @rcArgs | Select-Object -Last 6
if ($LASTEXITCODE -ge 8) { throw "robocopy failed with exit code $LASTEXITCODE" }

if ($FreshInstall) {
  Write-Host 'Restoring node_modules with npm ci ...'
  Push-Location $dst
  try {
    npm ci --no-audit --no-fund
    if ($LASTEXITCODE -ne 0) { throw 'npm ci failed' }
  } finally { Pop-Location }
}

$longest = (cmd /c "dir /s /b /a `"$dst`"" | Measure-Object Length -Maximum).Maximum
Write-Host ''
Write-Host "Done. Longest path at the destination: $longest characters (Windows Explorer limit: 260)."
if ($longest -ge 260) { Write-Warning 'Some paths exceed 260 characters. Use a shorter destination such as C:\Projects\INV-MOBILE-APP.' }
Write-Host 'If android\local.properties sdk.dir differs on this PC, update it, then build:'
Write-Host '  cd android; .\gradlew.bat assembleRelease -x lintVitalAnalyzeRelease -x lintVitalRelease'
